// Shape of the api.json files generated by `pnpm api` (the hk-extract-api CLI
// from @human-kit/markdown) and rendered by <ApiReference>.

export interface ApiProp {
	name: string;
	type: string;
	required: boolean;
	default: string | null;
	description: string;
}

export interface ApiDataAttribute {
	name: string;
	description: string;
}

export interface ApiPart {
	name: string;
	description: string;
	/**
	 * The element that a chart part makes, when the part also takes the attributes of
	 * that element. `null` for a chart part that takes only its own props. The other
	 * components do not write it: each of their parts takes the native attributes.
	 */
	element?: string | null;
	props: ApiProp[];
	dataAttributes: ApiDataAttribute[];
}

export interface ComponentApi {
	component: string;
	parts: ApiPart[];
}
